fixtures.src/types/extension.ts:
export type ExtensionMessageType = 
  | "GET_STATS"
  | "UPDATE_RULE"
  | "TOGGLE_BLOCKING"
  | "DOM_TELEMETRY"
  | "PING";

export interface ExtensionMessage<T = unknown> {
  readonly type: ExtensionMessageType;
  readonly payload: T;
  readonly senderId?: string;
  readonly timestamp: number;
}

export interface ExtensionResponse<T = unknown> {
  readonly success: boolean;
  readonly data?: T;
  readonly error?: string;
}

export interface DynamicRuleDefinition {
  readonly ruleId: number;
  readonly priority: number;
  readonly urlFilter: string;
  readonly action: "block" | "allow" | "redirect";
  readonly redirectUrl?: string;
  readonly domains?: readonly string[];
}

export interface PrivacyStats {
  readonly blockedRequestsCount: number;
  readonly monitoredDomains: readonly string[];
  readonly activeRulesCount: number;
  readonly sessionStartedAt: number;
}

export interface DomTelemetryPayload {
  readonly url: string;
  readonly trackerElementsFound: number;
  readonly insecureFormsDetected: number;
}

